def current_time(format, timezone=None, **_extra):
    import json, os, datetime
    from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0223000" if __import__("os").path.isdir("./environment_mix/0223000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _gen_id(prefix):
        import secrets
        return f"{prefix}_{secrets.token_hex(12)}"

    def _minute_start(dt):
        return dt.replace(second=0, microsecond=0)

    def _format_dt(dt_local, fmt):
        # Supported formats:
        # "h:mm A", "h:mm:ss A", "YYYY-MM-DD HH:mm:ss", "YYYY-MM-DD",
        # "YYYY-MM", "MM/DD/YYYY", "MM/DD/YY", "YYYY/MM/DD", "YYYY/MM"
        if fmt == "YYYY-MM-DD HH:mm:ss":
            return dt_local.strftime("%Y-%m-%d %H:%M:%S")
        if fmt == "YYYY-MM-DD":
            return dt_local.strftime("%Y-%m-%d")
        if fmt == "YYYY-MM":
            return dt_local.strftime("%Y-%m")
        if fmt == "MM/DD/YYYY":
            return dt_local.strftime("%m/%d/%Y")
        if fmt == "MM/DD/YY":
            return dt_local.strftime("%m/%d/%y")
        if fmt == "YYYY/MM/DD":
            return dt_local.strftime("%Y/%m/%d")
        if fmt == "YYYY/MM":
            return dt_local.strftime("%Y/%m")
        if fmt == "h:mm A":
            hour12 = dt_local.hour % 12
            hour12 = 12 if hour12 == 0 else hour12
            return f"{hour12}:{dt_local.minute:02d} {'AM' if dt_local.hour < 12 else 'PM'}"
        if fmt == "h:mm:ss A":
            hour12 = dt_local.hour % 12
            hour12 = 12 if hour12 == 0 else hour12
            return f"{hour12}:{dt_local.minute:02d}:{dt_local.second:02d} {'AM' if dt_local.hour < 12 else 'PM'}"
        return None

    allowed_formats = [
        "h:mm A",
        "h:mm:ss A",
        "YYYY-MM-DD HH:mm:ss",
        "YYYY-MM-DD",
        "YYYY-MM",
        "MM/DD/YYYY",
        "MM/DD/YY",
        "YYYY/MM/DD",
        "YYYY/MM",
    ]

    start = datetime.datetime.now(datetime.timezone.utc)
    request_params = {"format": format}
    if timezone is not None:
        request_params["timezone"] = timezone

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    tzreg = _load("timezone_registry.json")
    inv = _load("tool_invocations.json")
    counters = _load("rate_limit_counters.json")

    now = _now_utc()

    # auto-expire keys
    changed_keys = False
    for k in api_keys:
        if k.get("status") == "active" and k.get("expires_at"):
            exp = _parse_dt(k.get("expires_at"))
            if exp is not None and now >= exp.astimezone(datetime.timezone.utc):
                k["status"] = "expired"
                k["updated_at"] = _iso(now)
                changed_keys = True
    if changed_keys:
        _save("api_keys.json", api_keys)

    def _pick_auth_context():
        # Must find active workspace + active non-expired api key, and key scope allows tool (or empty scopes).
        # Also requires workspace has a usable default timezone if client omits timezone? No, can fall back to UTC.
        for ws in workspaces:
            if ws.get("status") != "active":
                continue
            # validate ws.default_timezone if present: must be enabled in registry (and valid ZoneInfo)
            dz = ws.get("default_timezone")
            if dz is not None:
                ok_reg = any(r.get("iana_name") == dz and r.get("status") == "enabled" for r in tzreg)
                if not ok_reg:
                    # workspace misconfigured; skip it as it cannot satisfy calls omitting timezone
                    # but if client supplies timezone, it still could work; we don't know yet, so do not skip here
                    pass
            # choose an api key for this workspace
            candidates = [k for k in api_keys if k.get("workspace_id") == ws.get("id")]
            for k in candidates:
                if k.get("status") != "active":
                    continue
                exp = _parse_dt(k.get("expires_at")) if k.get("expires_at") else None
                if exp is not None and now >= exp.astimezone(datetime.timezone.utc):
                    continue
                scopes = k.get("scopes") or []
                if scopes and "current_time" not in scopes:
                    continue
                return ws, k
        return None, None

    def _log_invocation(ws_id, key_id, status, normalized_time=None, normalized_date=None,
                        source_tz=None, target_tz=None, output_fmt=None, resp=None,
                        err_code=None, err_msg=None, duration_ms=None):
        t = _now_utc()
        row = {
            "id": _gen_id("inv"),
            "workspace_id": ws_id,
            "api_key_id": key_id,
            "tool_name": "current_time",
            "status": status,
            "request_params": request_params,
            "normalized_time": normalized_time,
            "normalized_date": normalized_date,
            "source_timezone": source_tz,
            "target_timezone": target_tz,
            "output_format": output_fmt,
            "response_payload": resp,
            "error_code": err_code,
            "error_message": err_msg,
            "duration_ms": duration_ms,
            "request_ip": None,
            "created_at": _iso(t),
            "updated_at": _iso(t),
        }
        inv.append(row)
        _save("tool_invocations.json", inv)

    # Validate inputs first (but still need to log, including UNAUTHORIZED)
    if not isinstance(format, str):
        # Need auth to log; if none possible, return unauthorized after best-effort log (not possible).
        ws, key = _pick_auth_context()
        if ws and key:
            _log_invocation(ws["id"], key["id"], "failed", output_fmt=None, err_code="VALIDATION_ERROR",
                            err_msg="format must be a string", duration_ms=0)
        return _err("VALIDATION_ERROR", "format must be a string")

    if format not in allowed_formats:
        ws, key = _pick_auth_context()
        if ws and key:
            _log_invocation(ws["id"], key["id"], "failed", output_fmt=None, err_code="INVALID_TIME_FORMAT",
                            err_msg="Unsupported format", duration_ms=0)
        return _err("VALIDATION_ERROR", "Unsupported format", error_code="INVALID_TIME_FORMAT")

    if timezone is not None and not isinstance(timezone, str):
        ws, key = _pick_auth_context()
        if ws and key:
            _log_invocation(ws["id"], key["id"], "failed", output_fmt=format, err_code="VALIDATION_ERROR",
                            err_msg="timezone must be a string", duration_ms=0)
        return _err("VALIDATION_ERROR", "timezone must be a string")

    ws, key = _pick_auth_context()
    if not ws or not key:
        # log unauthorized if any active workspace exists? rule says log invocation with failed/UNAUTHORIZED.
        # choose any active workspace for logging if possible
        ws_for_log = next((w for w in workspaces if w.get("status") == "active"), None)
        ws_id = ws_for_log.get("id") if ws_for_log else (workspaces[0].get("id") if workspaces else "unknown")
        _log_invocation(ws_id, None, "failed", output_fmt=format, err_code="UNAUTHORIZED",
                        err_msg="Unauthorized", duration_ms=0)
        return _err("UNAUTHORIZED", "Unauthorized")

    # Determine effective timezone: client param > workspace default > UTC
    eff_tz = timezone if timezone else (ws.get("default_timezone") or "UTC")

    # validate timezone: must be valid IANA and enabled in registry
    def _tz_enabled(name):
        return any(r.get("iana_name") == name and r.get("status") == "enabled" for r in tzreg)

    try:
        ZoneInfo(eff_tz)
    except ZoneInfoNotFoundError:
        _log_invocation(ws["id"], key["id"], "failed", output_fmt=format, source_tz=eff_tz,
                        err_code="INVALID_TIMEZONE", err_msg="Invalid IANA timezone", duration_ms=0)
        return _err("VALIDATION_ERROR", "Invalid IANA timezone", error_code="INVALID_TIMEZONE")

    if not _tz_enabled(eff_tz) and eff_tz != "UTC":
        _log_invocation(ws["id"], key["id"], "failed", output_fmt=format, source_tz=eff_tz,
                        err_code="INVALID_TIMEZONE", err_msg="Timezone not enabled", duration_ms=0)
        return _err("VALIDATION_ERROR", "Timezone not enabled", error_code="INVALID_TIMEZONE")

    # Rate limiting: increment bucket before executing
    window = _minute_start(now)
    window_iso = _iso(window)
    bucket = next((c for c in counters
                   if c.get("workspace_id") == ws["id"]
                   and c.get("api_key_id") == key["id"]
                   and c.get("window_start") == window_iso), None)
    if bucket is None:
        bucket = {
            "id": _gen_id("rlc"),
            "workspace_id": ws["id"],
            "api_key_id": key["id"],
            "window_start": window_iso,
            "count": 0,
            "status": "open",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        counters.append(bucket)

    if bucket.get("status") != "open":
        # treat non-open as not incrementable; start new open bucket with same key/window would violate unique,
        # so rate limit defensively.
        _log_invocation(ws["id"], key["id"], "rate_limited", output_fmt=format, source_tz=eff_tz,
                        err_code="RATE_LIMITED", err_msg="Rate limit counter not open",
                        duration_ms=0)
        return _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED")

    if (bucket.get("count") or 0) + 1 > int(ws.get("rate_limit_per_minute") or 0):
        _save("rate_limit_counters.json", counters)
        _log_invocation(ws["id"], key["id"], "rate_limited", output_fmt=format, source_tz=eff_tz,
                        err_code="RATE_LIMITED", err_msg="Rate limit exceeded", duration_ms=0)
        return _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED")

    bucket["count"] = int(bucket.get("count") or 0) + 1
    bucket["updated_at"] = _iso(now)
    _save("rate_limit_counters.json", counters)

    # update key last_used_at
    key["last_used_at"] = _iso(now)
    key["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    # Execute
    dt_local = now.astimezone(ZoneInfo(eff_tz))
    formatted = _format_dt(dt_local, format)
    if formatted is None:
        dur = int(((_now_utc() - start).total_seconds()) * 1000)
        _log_invocation(ws["id"], key["id"], "failed", output_fmt=format, source_tz=eff_tz,
                        err_code="INVALID_TIME_FORMAT", err_msg="Unsupported format", duration_ms=dur)
        return _err("VALIDATION_ERROR", "Unsupported format", error_code="INVALID_TIME_FORMAT")

    resp = {
        "formatted": formatted,
        "timezone": eff_tz,
        "iso": dt_local.isoformat(),
        "utc_iso": now.isoformat(),
        "format": format,
    }
    dur = int(((_now_utc() - start).total_seconds()) * 1000)
    _log_invocation(ws["id"], key["id"], "succeeded", output_fmt=format, source_tz=eff_tz,
                    resp=resp, duration_ms=dur)
    return resp

def relative_time(time, **_extra):
    import json, os, datetime
    from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0223000" if __import__("os").path.isdir("./environment_mix/0223000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _gen_id(prefix):
        import secrets
        return f"{prefix}_{secrets.token_hex(12)}"

    def _minute_start(dt):
        return dt.replace(second=0, microsecond=0)

    start = _now_utc()
    request_params = {"time": time}

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    tzreg = _load("timezone_registry.json")
    inv = _load("tool_invocations.json")
    counters = _load("rate_limit_counters.json")

    now = _now_utc()

    # auto-expire keys
    changed_keys = False
    for k in api_keys:
        if k.get("status") == "active" and k.get("expires_at"):
            exp = _parse_dt(k.get("expires_at"))
            if exp is not None and now >= exp.astimezone(datetime.timezone.utc):
                k["status"] = "expired"
                k["updated_at"] = _iso(now)
                changed_keys = True
    if changed_keys:
        _save("api_keys.json", api_keys)

    def _pick_auth_context():
        for ws in workspaces:
            if ws.get("status") != "active":
                continue
            candidates = [k for k in api_keys if k.get("workspace_id") == ws.get("id")]
            for k in candidates:
                if k.get("status") != "active":
                    continue
                exp = _parse_dt(k.get("expires_at")) if k.get("expires_at") else None
                if exp is not None and now >= exp.astimezone(datetime.timezone.utc):
                    continue
                scopes = k.get("scopes") or []
                if scopes and "relative_time" not in scopes:
                    continue
                return ws, k
        return None, None

    def _log_invocation(ws_id, key_id, status, normalized_time=None, err_code=None, err_msg=None, duration_ms=None):
        t = _now_utc()
        row = {
            "id": _gen_id("inv"),
            "workspace_id": ws_id,
            "api_key_id": key_id,
            "tool_name": "relative_time",
            "status": status,
            "request_params": request_params,
            "normalized_time": normalized_time,
            "normalized_date": None,
            "source_timezone": None,
            "target_timezone": None,
            "output_format": None,
            "response_payload": None,
            "error_code": err_code,
            "error_message": err_msg,
            "duration_ms": duration_ms,
            "request_ip": None,
            "created_at": _iso(t),
            "updated_at": _iso(t),
        }
        inv.append(row)
        _save("tool_invocations.json", inv)

    # Validate input type
    if not isinstance(time, str) or not time.strip():
        ws, key = _pick_auth_context()
        if ws and key:
            _log_invocation(ws["id"], key["id"], "failed", err_code="INVALID_TIME",
                            err_msg="time is required and must be a string", duration_ms=0)
        return _err("VALIDATION_ERROR", "time is required and must be a string", error_code="INVALID_TIME")

    ws, key = _pick_auth_context()
    if not ws or not key:
        ws_for_log = next((w for w in workspaces if w.get("status") == "active"), None)
        ws_id = ws_for_log.get("id") if ws_for_log else (workspaces[0].get("id") if workspaces else "unknown")
        _log_invocation(ws_id, None, "failed", err_code="UNAUTHORIZED", err_msg="Unauthorized", duration_ms=0)
        return _err("UNAUTHORIZED", "Unauthorized")

    # Effective timezone: workspace default or UTC
    eff_tz = ws.get("default_timezone") or "UTC"

    # validate timezone if not UTC: must be valid and enabled
    if eff_tz != "UTC":
        try:
            ZoneInfo(eff_tz)
        except ZoneInfoNotFoundError:
            _log_invocation(ws["id"], key["id"], "failed", err_code="INVALID_TIMEZONE",
                            err_msg="Workspace default timezone invalid", duration_ms=0)
            return _err("VALIDATION_ERROR", "Invalid timezone", error_code="INVALID_TIMEZONE")
        if not any(r.get("iana_name") == eff_tz and r.get("status") == "enabled" for r in tzreg):
            _log_invocation(ws["id"], key["id"], "failed", err_code="INVALID_TIMEZONE",
                            err_msg="Workspace default timezone not enabled", duration_ms=0)
            return _err("VALIDATION_ERROR", "Timezone not enabled", error_code="INVALID_TIMEZONE")

    # Rate limit increment
    window = _minute_start(now)
    window_iso = _iso(window)
    bucket = next((c for c in counters
                   if c.get("workspace_id") == ws["id"]
                   and c.get("api_key_id") == key["id"]
                   and c.get("window_start") == window_iso), None)
    if bucket is None:
        bucket = {
            "id": _gen_id("rlc"),
            "workspace_id": ws["id"],
            "api_key_id": key["id"],
            "window_start": window_iso,
            "count": 0,
            "status": "open",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        counters.append(bucket)

    if bucket.get("status") != "open":
        _log_invocation(ws["id"], key["id"], "rate_limited", err_code="RATE_LIMITED",
                        err_msg="Rate limit counter not open", duration_ms=0)
        return _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED")

    if (bucket.get("count") or 0) + 1 > int(ws.get("rate_limit_per_minute") or 0):
        _save("rate_limit_counters.json", counters)
        _log_invocation(ws["id"], key["id"], "rate_limited", err_code="RATE_LIMITED",
                        err_msg="Rate limit exceeded", duration_ms=0)
        return _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED")

    bucket["count"] = int(bucket.get("count") or 0) + 1
    bucket["updated_at"] = _iso(now)
    _save("rate_limit_counters.json", counters)

    key["last_used_at"] = _iso(now)
    key["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    # Parse time in effective timezone; normalized_time stored in UTC
    try:
        naive = datetime.datetime.strptime(time, "%Y-%m-%d %H:%M:%S")
    except Exception:
        dur = int(((_now_utc() - start).total_seconds()) * 1000)
        _log_invocation(ws["id"], key["id"], "failed", err_code="INVALID_TIME",
                        err_msg="time must be in YYYY-MM-DD HH:mm:ss", duration_ms=dur)
        return _err("VALIDATION_ERROR", "time must be in YYYY-MM-DD HH:mm:ss", error_code="INVALID_TIME")

    tzinfo = datetime.timezone.utc if eff_tz == "UTC" else ZoneInfo(eff_tz)
    local_dt = naive.replace(tzinfo=tzinfo)
    utc_dt = local_dt.astimezone(datetime.timezone.utc)

    # Compute relative string
    delta = utc_dt - now
    seconds = int(delta.total_seconds())
    future = seconds > 0
    abs_s = abs(seconds)

    def _unitize(abs_seconds):
        if abs_seconds < 60:
            return abs_seconds, "second"
        if abs_seconds < 3600:
            return abs_seconds // 60, "minute"
        if abs_seconds < 86400:
            return abs_seconds // 3600, "hour"
        if abs_seconds < 86400 * 30:
            return abs_seconds // 86400, "day"
        if abs_seconds < 86400 * 365:
            return abs_seconds // (86400 * 30), "month"
        return abs_seconds // (86400 * 365), "year"

    n, unit = _unitize(abs_s)
    if n == 1:
        phrase = f"in 1 {unit}" if future else f"1 {unit} ago"
    else:
        phrase = f"in {n} {unit}s" if future else f"{n} {unit}s ago"

    resp = {"relative": phrase}
    dur = int(((_now_utc() - start).total_seconds()) * 1000)
    _log_invocation(ws["id"], key["id"], "succeeded", normalized_time=_iso(utc_dt),
                    err_code=None, err_msg=None, duration_ms=dur)
    # retention: response_payload may be null; keep it null for this tool
    return resp

