        try:
            ZoneInfo(eff_tz)
        except ZoneInfoNotFoundError:
            _log_invocation(ws["id"], key["id"], "failed", err_code="INVALID_TIMEZONE",
                            err_msg="Workspace default timezone invalid", duration_ms=0)
            return _err("VALIDATION_ERROR", "Invalid timezone", error_code="INVALID_TIMEZONE")
