def get_timestamp(time=None, **_extra):
    import json, os, datetime
    from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0223000" if __import__("os").path.isdir("./environment_mix/0223000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _gen_id(prefix):
        import secrets
        return f"{prefix}_{secrets.token_hex(12)}"

    def _minute_start(dt):
        return dt.replace(second=0, microsecond=0)

    start = _now_utc()
    request_params = {}
    if time is not None:
        request_params["time"] = time

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    tzreg = _load("timezone_registry.json")
    inv = _load("tool_invocations.json")
    counters = _load("rate_limit_counters.json")

    now = _now_utc()

    # auto-expire keys
    changed_keys = False
    for k in api_keys:
        if k.get("status") == "active" and k.get("expires_at"):
            exp = _parse_dt(k.get("expires_at"))
            if exp is not None and now >= exp.astimezone(datetime.timezone.utc):
                k["status"] = "expired"
                k["updated_at"] = _iso(now)
                changed_keys = True
    if changed_keys:
        _save("api_keys.json", api_keys)

    def _pick_auth_context():
        for ws in workspaces:
            if ws.get("status") != "active":
                continue
            candidates = [k for k in api_keys if k.get("workspace_id") == ws.get("id")]
            for k in candidates:
                if k.get("status") != "active":
                    continue
                exp = _parse_dt(k.get("expires_at")) if k.get("expires_at") else None
                if exp is not None and now >= exp.astimezone(datetime.timezone.utc):
                    continue
                scopes = k.get("scopes") or []
                if scopes and "get_timestamp" not in scopes:
                    continue
                return ws, k
        return None, None

    def _log_invocation(ws_id, key_id, status, normalized_time=None, err_code=None, err_msg=None, duration_ms=None):
        t = _now_utc()
        row = {
            "id": _gen_id("inv"),
            "workspace_id": ws_id,
            "api_key_id": key_id,
            "tool_name": "get_timestamp",
            "status": status,
            "request_params": request_params,
            "normalized_time": normalized_time,
            "normalized_date": None,
            "source_timezone": None,
            "target_timezone": None,
            "output_format": None,
            "response_payload": None,
            "error_code": err_code,
            "error_message": err_msg,
            "duration_ms": duration_ms,
            "request_ip": None,
            "created_at": _iso(t),
            "updated_at": _iso(t),
        }
        inv.append(row)
        _save("tool_invocations.json", inv)

    if time is not None and not isinstance(time, str):
        ws, key = _pick_auth_context()
        if ws and key:
            _log_invocation(ws["id"], key["id"], "failed", err_code="INVALID_TIME",
                            err_msg="time must be a string in YYYY-MM-DD HH:mm:ss", duration_ms=0)
        return _err("VALIDATION_ERROR", "time must be a string in YYYY-MM-DD HH:mm:ss", error_code="INVALID_TIME")

    ws, key = _pick_auth_context()
    if not ws or not key:
        ws_for_log = next((w for w in workspaces if w.get("status") == "active"), None)
        ws_id = ws_for_log.get("id") if ws_for_log else (workspaces[0].get("id") if workspaces else "unknown")
        _log_invocation(ws_id, None, "failed", err_code="UNAUTHORIZED", err_msg="Unauthorized", duration_ms=0)
        return _err("UNAUTHORIZED", "Unauthorized")

    # Effective timezone for parsing/now
    eff_tz = ws.get("default_timezone") or "UTC"
    if eff_tz != "UTC":
        try:
            ZoneInfo(eff_tz)
        except ZoneInfoNotFoundError:
            _log_invocation(ws["id"], key["id"], "failed", err_code="INVALID_TIMEZONE",
                            err_msg="Workspace default timezone invalid", duration_ms=0)
            return _err("VALIDATION_ERROR", "Invalid timezone", error_code="INVALID_TIMEZONE")
        if not any(r.get("iana_name") == eff_tz and r.get("status") == "enabled" for r in tzreg):
            _log_invocation(ws["id"], key["id"], "failed", err_code="INVALID_TIMEZONE",
                            err_msg="Workspace default timezone not enabled", duration_ms=0)
            return _err("VALIDATION_ERROR", "Timezone not enabled", error_code="INVALID_TIMEZONE")

    # Rate limiting
    window = _minute_start(now)
    window_iso = _iso(window)
    bucket = next((c for c in counters
                   if c.get("workspace_id") == ws["id"]
                   and c.get("api_key_id") == key["id"]
                   and c.get("window_start") == window_iso), None)
    if bucket is None:
        bucket = {
            "id": _gen_id("rlc"),
            "workspace_id": ws["id"],
            "api_key_id": key["id"],
            "window_start": window_iso,
            "count": 0,
            "status": "open",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        counters.append(bucket)

    if bucket.get("status") != "open":
        _log_invocation(ws["id"], key["id"], "rate_limited", err_code="RATE_LIMITED",
                        err_msg="Rate limit counter not open", duration_ms=0)
        return _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED")

    if (bucket.get("count") or 0) + 1 > int(ws.get("rate_limit_per_minute") or 0):
        _save("rate_limit_counters.json", counters)
        _log_invocation(ws["id"], key["id"], "rate_limited", err_code="RATE_LIMITED",
                        err_msg="Rate limit exceeded", duration_ms=0)
        return _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED")

    bucket["count"] = int(bucket.get("count") or 0) + 1
    bucket["updated_at"] = _iso(now)
    _save("rate_limit_counters.json", counters)

    key["last_used_at"] = _iso(now)
    key["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    tzinfo = datetime.timezone.utc if eff_tz == "UTC" else ZoneInfo(eff_tz)

    if time is None:
        local_dt = now.astimezone(tzinfo)
    else:
        try:
            naive = datetime.datetime.strptime(time, "%Y-%m-%d %H:%M:%S")
        except Exception:
            dur = int(((_now_utc() - start).total_seconds()) * 1000)
            _log_invocation(ws["id"], key["id"], "failed", err_code="INVALID_TIME",
                            err_msg="time must be in YYYY-MM-DD HH:mm:ss", duration_ms=dur)
            return _err("VALIDATION_ERROR", "time must be in YYYY-MM-DD HH:mm:ss", error_code="INVALID_TIME")
        local_dt = naive.replace(tzinfo=tzinfo)

    utc_dt = local_dt.astimezone(datetime.timezone.utc)
    ts = int(utc_dt.timestamp())

    resp = {"timestamp": ts, "utc_iso": utc_dt.isoformat()}
    dur = int(((_now_utc() - start).total_seconds()) * 1000)
    _log_invocation(ws["id"], key["id"], "succeeded", normalized_time=_iso(utc_dt), duration_ms=dur)
    return resp

def get_week_year(date=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0223000" if __import__("os").path.isdir("./environment_mix/0223000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = datetime.datetime.now(datetime.timezone.utc)

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _dt_to_iso_z(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        t = s.strip()
        if t.endswith("Z"):
            t = t[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(t)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _minute_bucket(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.replace(second=0, microsecond=0)

    def _gen_id(prefix):
        return f"{prefix}_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S%f')}"

    def _get_zoneinfo(name):
        try:
            from zoneinfo import ZoneInfo
        except Exception:
            return None
        try:
            return ZoneInfo(name)
        except Exception:
            return None

    def _auto_expire_keys(keys, now_dt):
        changed = False
        now_iso = now_dt.isoformat().replace("+00:00", "Z")
        for k in keys:
            if k.get("status") == "active":
                exp = _parse_rfc3339(k.get("expires_at")) if k.get("expires_at") else None
                if exp is not None and now_dt >= exp:
                    k["status"] = "expired"
                    k["updated_at"] = now_iso
                    changed = True
        return changed

    def _resolve_auth(workspaces, keys):
        now_dt = _now_utc()
        if _auto_expire_keys(keys, now_dt):
            _save("api_keys.json", keys)

        scope_needed = "time:calendar"
        for ws in workspaces:
            if ws.get("status") != "active":
                continue
            ws_id = ws.get("id")
            for k in keys:
                if k.get("workspace_id") != ws_id:
                    continue
                if k.get("status") != "active":
                    continue
                exp = _parse_rfc3339(k.get("expires_at")) if k.get("expires_at") else None
                if exp is not None and now_dt >= exp:
                    continue
                scopes = k.get("scopes")
                if isinstance(scopes, list) and len(scopes) > 0 and scope_needed not in scopes:
                    continue
                return ws, k
        return None, None

    def _finalize(inv, status, response_payload=None, error_code=None, error_message=None, normalized_date=None):
        ended = _now_utc()
        inv["status"] = status
        inv["updated_at"] = ended.isoformat().replace("+00:00", "Z")
        inv["duration_ms"] = max(0, int((ended - started).total_seconds() * 1000))
        inv["response_payload"] = response_payload
        inv["error_code"] = error_code
        inv["error_message"] = error_message
        inv["normalized_date"] = normalized_date

    # validate param type (if provided)
    if date is not None and not isinstance(date, str):
        workspaces = _load("workspaces.json")
        keys = _load("api_keys.json")
        inv_rows = _load("tool_invocations.json")
        ws, k = _resolve_auth(workspaces, keys)
        now_iso = _now_utc().isoformat().replace("+00:00", "Z")
        inv = {
            "id": _gen_id("inv"),
            "workspace_id": ws.get("id") if ws else "unknown",
            "api_key_id": k.get("id") if k else None,
            "tool_name": "get_week_year",
            "status": "accepted",
            "request_params": {"date": date},
            "normalized_time": None,
            "normalized_date": None,
            "source_timezone": None,
            "target_timezone": None,
            "output_format": None,
            "response_payload": None,
            "error_code": None,
            "error_message": None,
            "duration_ms": None,
            "request_ip": None,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        inv_rows.append(inv)
        _finalize(inv_rows[-1], "failed", None, "VALIDATION_ERROR", "date must be a string in 'YYYY-MM-DD' format.", None)
        _save("tool_invocations.json", inv_rows)
        return _err("VALIDATION_ERROR", "date must be a string.", vendor_error="INVALID_ARGUMENT")

    workspaces = _load("workspaces.json")
    keys = _load("api_keys.json")
    inv_rows = _load("tool_invocations.json")
    counters = _load("rate_limit_counters.json")

    ws, k = _resolve_auth(workspaces, keys)
    now = _now_utc()
    now_iso = now.isoformat().replace("+00:00", "Z")

    inv = {
        "id": _gen_id("inv"),
        "workspace_id": ws.get("id") if ws else "unknown",
        "api_key_id": k.get("id") if k else None,
        "tool_name": "get_week_year",
        "status": "accepted",
        "request_params": {"date": date} if date is not None else {},
        "normalized_time": None,
        "normalized_date": None,
        "source_timezone": None,
        "target_timezone": None,
        "output_format": None,
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "request_ip": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    inv_rows.append(inv)

    if ws is None or k is None:
        _finalize(inv_rows[-1], "failed", None, "UNAUTHORIZED", "No authorized workspace/api key available.", None)
        _save("tool_invocations.json", inv_rows)
        return _err("UNAUTHORIZED", "Unauthorized", vendor_error="UNAUTHENTICATED")

    if ws.get("status") != "active":
        _finalize(inv_rows[-1], "failed", None, "UNAUTHORIZED", "Workspace is not active.", None)
        _save("tool_invocations.json", inv_rows)
        return _err("UNAUTHORIZED", "Workspace is not active.", vendor_error="UNAUTHORIZED")

    # Rate limit
    window = _minute_bucket(now)
    window_iso = window.isoformat().replace("+00:00", "Z")
    ws_limit = ws.get("rate_limit_per_minute")
    if not isinstance(ws_limit, int) or ws_limit < 1:
        ws_limit = 60

    def _find_counter():
        for r in counters:
            if r.get("workspace_id") == ws.get("id") and r.get("api_key_id") == k.get("id") and r.get("window_start") == window_iso:
                return r
        return None

    c = _find_counter()
    if c is None:
        c = {
            "id": _gen_id("rl"),
            "workspace_id": ws.get("id"),
            "api_key_id": k.get("id"),
            "window_start": window_iso,
            "count": 0,
            "status": "open",
            "created_at": now_iso,
            "updated_at": now_iso
        }
        counters.append(c)

    if not isinstance(c.get("count"), int) or c["count"] < 0:
        c["count"] = 0
    if c["count"] + 1 > ws_limit:
        _finalize(inv_rows[-1], "rate_limited", None, "RATE_LIMITED", "Rate limit exceeded.", None)
        _save("tool_invocations.json", inv_rows)
        _save("rate_limit_counters.json", counters)
        return _err("RATE_LIMIT", "Rate limit exceeded.", vendor_error="RESOURCE_EXHAUSTED")

    c["count"] += 1
    c["updated_at"] = now_iso
    _save("rate_limit_counters.json", counters)

    # Update key last_used_at
    k["last_used_at"] = now_iso
    k["updated_at"] = now_iso
    _save("api_keys.json", keys)

    # Effective timezone for "today"
    tz_name = ws.get("default_timezone") or "UTC"
    zone = _get_zoneinfo(tz_name) if tz_name != "UTC" else datetime.timezone.utc
    if zone is None:
        # workspace default_timezone invalid; treat as UTC (but do not mutate workspace here)
        zone = datetime.timezone.utc
        tz_name = "UTC"

    if date is None:
        local_today = now.astimezone(zone).date()
        dt = datetime.date(local_today.year, local_today.month, local_today.day)
        norm_date = dt.strftime("%Y-%m-%d")
    else:
        try:
            dt = datetime.datetime.strptime(date, "%Y-%m-%d").date()
        except ValueError:
            _finalize(inv_rows[-1], "failed", None, "INVALID_DATE", "date must be in 'YYYY-MM-DD' format and valid.", None)
            _save("tool_invocations.json", inv_rows)
            return _err("VALIDATION_ERROR", "Invalid date; expected 'YYYY-MM-DD' and a valid calendar date.", vendor_error="INVALID_ARGUMENT", error_code="INVALID_DATE")
        norm_date = dt.strftime("%Y-%m-%d")

    # week-of-year (simple, Sunday-based) and ISO week
    # week: 1 + number of Sundays passed since Jan 1 (Sunday starts new week)
    jan1 = datetime.date(dt.year, 1, 1)
    days_since = (dt - jan1).days
    week = 1 + ((days_since + (jan1.weekday() + 1) % 7) // 7)  # align so Sunday=0 boundary
    iso_year, iso_week, iso_weekday = dt.isocalendar()

    payload = {
        "date": norm_date,
        "week": int(week),
        "isoWeek": int(iso_week),
        "isoYear": int(iso_year)
    }
    _finalize(inv_rows[-1], "succeeded", payload, None, None, normalized_date=norm_date)
    _save("tool_invocations.json", inv_rows)
    return payload

