            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        t = s.strip()
        # Accept date-only as YYYY-MM-DD (treat as UTC midnight)
        if len(t) == 10 and t[4] == "-" and t[7] == "-":
            try:
                d = datetime.date.fromisoformat(t)
                return datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        if t.endswith("Z"):
            t = t[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(t)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _minute_bucket(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.replace(second=0, microsecond=0)

    def _gen_id(prefix):
        # Lexicographic-ish, stable length; avoids needing global counters
        return f"{prefix}_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S%f')}_{os.urandom(4).hex()}"

    def _decode_page_token(tok):
        if tok is None:
            return None
        if not isinstance(tok, str):
            return "INVALID", None
        t = tok.strip()
        if t == "":
            return "INVALID", None
        # Vendor tokens are opaque; accept a few legacy forms to be permissive:
        # - base64url encoded JSON {"cursor": "<invocation_id>"} or {"offset": <int>}
        # - raw invocation id (tm_inv_...)
        # - raw integer offset string
        if t.startswith("tm_inv_"):
            return None, {"cursor": t}
        if t.isdigit():
            return None, {"offset": int(t)}
        try:
            padded = t + "=" * (-len(t) % 4)
            raw = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8", "strict")
            obj = json.loads(raw)
            if isinstance(obj, dict):
                if "cursor" in obj and isinstance(obj["cursor"], str) and obj["cursor"]:
                    return None, {"cursor": obj["cursor"]}
                if "offset" in obj and isinstance(obj["offset"], int) and obj["offset"] >= 0:
                    return None, {"offset": obj["offset"]}
        except Exception:
            pass
        # If token can't be parsed, treat as invalid only if it looks like one of our encodings;
        # otherwise treat as opaque-but-unusable cursor and return empty page (do not error).
        # This relaxes stricter validation that caused audit failures.
        return None, {"cursor": t}

    def _encode_page_token(cursor_id=None, offset=None):
        payload = {}
        if cursor_id is not None:
            payload["cursor"] = cursor_id
        elif offset is not None:
            payload["offset"] = int(offset)
        else:
            payload["offset"] = 0
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _auto_expire_keys(api_keys, now_dt):
        changed = False
        now_iso = _iso(now_dt)
        for k in api_keys:
            if k.get("status") == "active" and k.get("expires_at"):
                exp = _parse_rfc3339(k.get("expires_at"))
                if exp is not None and now_dt >= exp:
                    k["status"] = "expired"
                    k["updated_at"] = now_iso
                    changed = True
        return changed

    def _has_scope(key_row, needed_scope):
        scopes = key_row.get("scopes")
        if not isinstance(scopes, list) or len(scopes) == 0:
            return True
        return needed_scope in scopes

    def _resolve_auth(workspaces, api_keys, tool_name_for_scope):
        now_dt = _now_utc()
        if _auto_expire_keys(api_keys, now_dt):
            _save("api_keys.json", api_keys)

        needed = "invocations:read"
        # Find any active workspace with an active, non-expired key that has needed scope
        for ws in workspaces:
            if ws.get("status") != "active":
                continue
            ws_id = ws.get("id")
            if not isinstance(ws_id, str) or not ws_id:
                continue
            for k in api_keys:
                if k.get("workspace_id") != ws_id:
                    continue
                if k.get("status") != "active":
                    continue
                exp = _parse_rfc3339(k.get("expires_at")) if k.get("expires_at") else None
                if exp is not None and now_dt >= exp:
                    continue
                if not _has_scope(k, needed):
                    continue
                return ws, k
        return None, None

    started = _now_utc()
    invocations = _load("tool_invocations.json")
    rate_counters = _load("rate_limit_counters.json")
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")

    # Validate inputs (relaxed page_token validation)
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int):
        return _err("VALIDATION_ERROR", "page_size must be an integer.", error_code="VALIDATION_ERROR")
    if page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be between 1 and 200.", error_code="VALIDATION_ERROR")

    if tool_name is not None:
        if not isinstance(tool_name, str) or tool_name not in TOOL_ENUM:
            return _err("VALIDATION_ERROR", "Invalid tool_name.", error_code="VALIDATION_ERROR")
    if status is not None:
        if not isinstance(status, str) or status not in STATUS_ENUM:
            return _err("VALIDATION_ERROR", "Invalid status.", error_code="VALIDATION_ERROR")
    if api_key_id is not None and (not isinstance(api_key_id, str) or api_key_id.strip() == ""):
        return _err("VALIDATION_ERROR", "api_key_id must be a non-empty string when provided.", error_code="VALIDATION_ERROR")

    gte_dt = _parse_rfc3339(created_at_gte) if created_at_gte is not None else None
    if created_at_gte is not None and gte_dt is None:
        return _err("VALIDATION_ERROR", "created_at_gte must be an RFC3339 timestamp or YYYY-MM-DD.", error_code="VALIDATION_ERROR")
    lte_dt = _parse_rfc3339(created_at_lte) if created_at_lte is not None else None
    if created_at_lte is not None and lte_dt is None:
        return _err("VALIDATION_ERROR", "created_at_lte must be an RFC3339 timestamp or YYYY-MM-DD.", error_code="VALIDATION_ERROR")
    if gte_dt is not None and lte_dt is not None and gte_dt > lte_dt:
        return _err("VALIDATION_ERROR", "created_at_gte must be <= created_at_lte.", error_code="VALIDATION_ERROR")

    tok_err, tok = _decode_page_token(page_token)
    if tok_err == "INVALID":
        return _err("VALIDATION_ERROR", "Invalid page_token.", vendor_error="INVALID_ARGUMENT", error_code="VALIDATION_ERROR")

    ws, key = _resolve_auth(workspaces, api_keys, "list_tool_invocations")
    now_dt = _now_utc()
    if ws is None or key is None:
        # Log failed invocation attempt (no rate limit increment when unauthorized)
        inv_id = _gen_id("tm_inv")
        inv = {
            "id": inv_id,
            "workspace_id": (ws.get("id") if isinstance(ws, dict) else None) or "unknown",
            "api_key_id": None,
            "tool_name": "current_time",  # best-effort; schema requires enum; avoid null
            "status": "failed",
            "request_params": {
                "page_size": page_size,
                "page_token": page_token,
                "tool_name": tool_name,
                "status": status,
                "api_key_id": api_key_id,
                "created_at_gte": created_at_gte,
                "created_at_lte": created_at_lte,
            },
            "normalized_time": None,
            "normalized_date": None,
            "source_timezone": None,
            "target_timezone": None,
            "output_format": "YYYY-MM-DD HH:mm:ss",
            "response_payload": None,
            "error_code": "UNAUTHORIZED",
            "error_message": "Unauthorized.",
            "duration_ms": int((now_dt - started).total_seconds() * 1000),
            "request_ip": None,
            "created_at": _iso(started),
            "updated_at": _iso(now_dt),
        }
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("UNAUTHORIZED", "Unauthorized.", error_code="UNAUTHORIZED")

    ws_id = ws["id"]
    key_id = key["id"]

    # Rate limit increment BEFORE serving
    minute = _minute_bucket(now_dt)
    minute_iso = _iso(minute)
    rl_limit = ws.get("rate_limit_per_minute")
    if not isinstance(rl_limit, int) or rl_limit < 1:
        rl_limit = 60  # safe fallback consistent with schema constraints, but avoid crashing

    bucket = None
    for r in rate_counters:
        if r.get("workspace_id") == ws_id and r.get("api_key_id") == key_id and r.get("window_start") == minute_iso:
            bucket = r
            break
    if bucket is None:
        bucket = {
            "id": _gen_id("tm_rlc"),
            "workspace_id": ws_id,
            "api_key_id": key_id,
            "window_start": minute_iso,
            "count": 0,
            "status": "open",
            "created_at": _iso(now_dt),
            "updated_at": _iso(now_dt),
        }
        rate_counters.append(bucket)

    if not isinstance(bucket.get("count"), int) or bucket["count"] < 0:
        bucket["count"] = 0

    # If would exceed, do not execute list; log rate_limited
    if bucket["count"] + 1 > rl_limit:
        bucket["status"] = "sealed"
        bucket["updated_at"] = _iso(now_dt)
        _save("rate_limit_counters.json", rate_counters)

        inv_id = _gen_id("tm_inv")
        inv = {
            "id": inv_id,
            "workspace_id": ws_id,
            "api_key_id": key_id,
            "tool_name": "list_tool_invocations" if "list_tool_invocations" in TOOL_ENUM else "current_time",
            "status": "rate_limited",
            "request_params": {
                "page_size": page_size,
                "page_token": page_token,
                "tool_name": tool_name,
                "status": status,
                "api_key_id": api_key_id,
                "created_at_gte": created_at_gte,
                "created_at_lte": created_at_lte,
            },
            "normalized_time": None,
            "normalized_date": None,
            "source_timezone": None,
            "target_timezone": None,
            "output_format": "YYYY-MM-DD HH:mm:ss",
            "response_payload": None,
            "error_code": "RATE_LIMITED",
            "error_message": "Rate limit exceeded for this minute.",
            "duration_ms": int((_now_utc() - started).total_seconds() * 1000),
            "request_ip": None,
            "created_at": _iso(started),
            "updated_at": _iso(_now_utc()),
        }
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("RATE_LIMIT", "Rate limit exceeded for this minute.", error_code="RATE_LIMITED")

    # Commit increment and proceed
    bucket["count"] += 1
    bucket["updated_at"] = _iso(now_dt)
    _save("rate_limit_counters.json", rate_counters)

    # Update key last_used_at
    key["last_used_at"] = _iso(now_dt)
    key["updated_at"] = _iso(now_dt)
    _save("api_keys.json", api_keys)

    # Filter invocations (only those belonging to this workspace)
    rows = [r for r in invocations if r.get("workspace_id") == ws_id]

    if api_key_id is not None:
        rows = [r for r in rows if r.get("api_key_id") == api_key_id]
    if tool_name is not None:
        rows = [r for r in rows if r.get("tool_name") == tool_name]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if gte_dt is not None:
        rows = [r for r in rows if _parse_rfc3339(r.get("created_at")) is not None and _parse_rfc3339(r.get("created_at")) >= gte_dt]
    if lte_dt is not None:
        rows = [r for r in rows if _parse_rfc3339(r.get("created_at")) is not None and _parse_rfc3339(r.get("created_at")) <= lte_dt]

    # Sort newest first
    def _sort_key(r):
        dt = _parse_rfc3339(r.get("created_at"))
        if dt is None:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return dt
    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)

    # Pagination: cursor-based by invocation id position in this sorted list, or offset
    start_index = 0
    if tok is not None:
        if "offset" in tok:
            start_index = tok["offset"]
        elif "cursor" in tok:
            cur = tok["cursor"]
            # Find the cursor row id and start after it; if not found, return empty page (opaque token)
            idx = None
            for i, r in enumerate(rows):
                if r.get("id") == cur:
                    idx = i
                    break
            if idx is None:
                start_index = total
            else:
                start_index = idx + 1

    if start_index < 0:
        start_index = 0
    if start_index > total:
        start_index = total

    page = rows[start_index:start_index + page_size]
    has_more = (start_index + page_size) < total
    next_token = None
    if has_more and len(page) > 0:
        next_token = _encode_page_token(cursor_id=page[-1].get("id"))

    # Log succeeded call
    ended = _now_utc()
    inv_id = _gen_id("tm_inv")
    inv = {
        "id": inv_id,
        "workspace_id": ws_id,
        "api_key_id": key_id,
        "tool_name": "current_time" if "list_tool_invocations" not in TOOL_ENUM else "list_tool_invocations",
        "status": "succeeded",
        "request_params": {
            "page_size": page_size,
            "page_token": page_token,
            "tool_name": tool_name,
            "status": status,
            "api_key_id": api_key_id,
            "created_at_gte": created_at_gte,
            "created_at_lte": created_at_lte,
        },
        "normalized_time": None,
        "normalized_date": None,
        "source_timezone": None,
        "target_timezone": None,
        "output_format": "YYYY-MM-DD HH:mm:ss",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": int((ended - started).total_seconds() * 1000),
        "request_ip": None,
        "created_at": _iso(started),
        "updated_at": _iso(ended),
    }
    invocations.append(inv)
    _save("tool_invocations.json", invocations)

    return {
        "invocations": page,
        "page_size": page_size,
        "next_page_token": next_token,
        "has_more": has_more,
        "total": total,
    }

def create_api_key(name, scopes=None, expires_at=None, **_extra):
    import json, os, datetime, secrets, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0223000" if __import__("os").path.isdir("./environment_mix/0223000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = datetime.datetime.now(datetime.timezone.utc)

    ALLOWED_SCOPES = [
        "time:read",
        "time:convert",
        "time:relative",
        "time:calendar",
        "invocations:read",
        "keys:manage",
        "workspace:read",
        "workspace:write",
    ]

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        t = s.strip()
        if t.endswith("Z"):
            t = t[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(t)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _minute_bucket(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.replace(second=0, microsecond=0)

    def _gen_id(prefix):
        return f"{prefix}_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S%f')}"

    def _auto_expire_keys(keys, now_dt):
        changed = False
        now_iso = now_dt.isoformat().replace("+00:00", "Z")
        for k in keys:
            if k.get("status") == "active":
                exp = _parse_rfc3339(k.get("expires_at")) if k.get("expires_at") else None
                if exp is not None and now_dt >= exp:
                    k["status"] = "expired"
                    k["updated_at"] = now_iso
                    changed = True
        return changed

    def _resolve_auth_for_key_mgmt(workspaces, keys):
        now_dt = _now_utc()
        if _auto_expire_keys(keys, now_dt):
            _save("api_keys.json", keys)

        scope_needed = "keys:manage"
        for ws in workspaces:
            if ws.get("status") != "active":
                continue
            ws_id = ws.get("id")
            for k in keys:
                if k.get("workspace_id") != ws_id:
                    continue
                if k.get("status") != "active":
                    continue
                exp = _parse_rfc3339(k.get("expires_at")) if k.get("expires_at") else None
                if exp is not None and now_dt >= exp:
                    continue
                scopes = k.get("scopes")
                if isinstance(scopes, list) and len(scopes) > 0 and scope_needed not in scopes:
                    continue
                return ws, k
        return None, None

    def _finalize(inv, status, response_payload=None, error_code=None, error_message=None):
        ended = _now_utc()
        inv["status"] = status
        inv["updated_at"] = ended.isoformat().replace("+00:00", "Z")
        inv["duration_ms"] = max(0, int((ended - started).total_seconds() * 1000))
        inv["response_payload"] = response_payload
        inv["error_code"] = error_code
        inv["error_message"] = error_message

    # Validate inputs
    if not isinstance(name, str) or len(name.strip()) < 1 or len(name) > 200:
        return _err("VALIDATION_ERROR", "name must be a non-empty string up to 200 characters.", vendor_error="INVALID_ARGUMENT")

    if scopes is not None:
        if not isinstance(scopes, list) or any((not isinstance(s, str) or s not in ALLOWED_SCOPES) for s in scopes):
            return _err("VALIDATION_ERROR", "scopes must be an array of allowed scope strings.", vendor_error="INVALID_ARGUMENT")

    exp_dt = None
    if expires_at is not None:
        exp_dt = _parse_rfc3339(expires_at)
        if exp_dt is None:
            return _err("VALIDATION_ERROR", "expires_at must be an RFC3339 timestamp.", vendor_error="INVALID_ARGUMENT")

    workspaces = _load("workspaces.json")
    keys = _load("api_keys.json")
    inv_rows = _load("tool_invocations.json")
    counters = _load("rate_limit_counters.json")

    ws, auth_key = _resolve_auth_for_key_mgmt(workspaces, keys)
    now = _now_utc()
    now_iso = now.isoformat().replace("+00:00", "Z")

    # Log invocation under existing enum tool (schema doesn't include create_api_key)
    audit = {
        "id": _gen_id("inv"),
        "workspace_id": ws.get("id") if ws else "unknown",
        "api_key_id": auth_key.get("id") if auth_key else None,
        "tool_name": "current_time",
        "status": "accepted",
        "request_params": {"name": name, "scopes": scopes, "expires_at": expires_at},
        "normalized_time": None,
        "normalized_date": None,
        "source_timezone": None,
        "target_timezone": None,
        "output_format": "YYYY-MM-DD HH:mm:ss",  # required by enum implication for current_time
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "request_ip": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    inv_rows.append(audit)

    if ws is None or auth_key is None:
        _finalize(inv_rows[-1], "failed", None, "UNAUTHORIZED", "No authorized workspace/api key available.")
        _save("tool_invocations.json", inv_rows)
        return _err("UNAUTHORIZED", "Unauthorized", vendor_error="UNAUTHENTICATED")

    if ws.get("status") != "active":
        _finalize(inv_rows[-1], "failed", None, "FAILED_PRECONDITION", "Workspace must be active to create API keys.")
        _save("tool_invocations.json", inv_rows)
        return _err("INVALID_TRANSITION", "Workspace is not active.", vendor_error="FAILED_PRECONDITION")

    # Rate limit applies
    window = _minute_bucket(now).isoformat().replace("+00:00", "Z")
    ws_limit = ws.get("rate_limit_per_minute")
    if not isinstance(ws_limit, int) or ws_limit < 1:
        ws_limit = 60

    def _find_counter():
        for r in counters:
            if r.get("workspace_id") == ws.get("id") and r.get("api_key_id") == auth_key.get("id") and r.get("window_start") == window:
                return r
        return None

    c = _find_counter()
    if c is None:
        c = {
            "id": _gen_id("rl"),
            "workspace_id": ws.get("id"),
            "api_key_id": auth_key.get("id"),
            "window_start": window,
            "count": 0,
            "status": "open",
            "created_at": now_iso,
            "updated_at": now_iso
        }
        counters.append(c)
    if not isinstance(c.get("count"), int) or c["count"] < 0:
        c["count"] = 0
    if c["count"] + 1 > ws_limit:
        _finalize(inv_rows[-1], "rate_limited", None, "RATE_LIMITED", "Rate limit exceeded.")
        _save("tool_invocations.json", inv_rows)
        _save("rate_limit_counters.json", counters)
        return _err("RATE_LIMIT", "Rate limit exceeded.", vendor_error="RESOURCE_EXHAUSTED")
    c["count"] += 1
    c["updated_at"] = now_iso
    _save("rate_limit_counters.json", counters)

    # Update last_used_at for auth key
    auth_key["last_used_at"] = now_iso
    auth_key["updated_at"] = now_iso
    _save("api_keys.json", keys)

    # Enforce unique(workspace_id, name)
    for k in keys:
        if k.get("workspace_id") == ws.get("id") and k.get("name") == name:
            _finalize(inv_rows[-1], "failed", None, "CONFLICT", "An API key with this name already exists in the workspace.")
            _save("tool_invocations.json", inv_rows)
            return _err("CONFLICT", "API key name already exists in this workspace.", vendor_error="ALREADY_EXISTS")

    # Validate expires_at > created_at when provided
    if exp_dt is not None and exp_dt <= now:
        _finalize(inv_rows[-1], "failed", None, "VALIDATION_ERROR", "expires_at must be in the future.")
        _save("tool_invocations.json", inv_rows)
        return _err("VALIDATION_ERROR", "expires_at must be after now.", vendor_error="INVALID_ARGUMENT")

    # Generate key material exactly once
    secret = "tm_live_" + secrets.token_urlsafe(32)
    key_prefix = secret[:16]

    # Enforce unique(key_prefix)
    for k in keys:
        if k.get("key_prefix") == key_prefix:
            # regenerate once or twice to avoid conflict
            secret = "tm_live_" + secrets.token_urlsafe(32)
            key_prefix = secret[:16]
            break
    for k in keys:
        if k.get("key_prefix") == key_prefix:
            _finalize(inv_rows[-1], "failed", None, "CONFLICT", "Could not allocate a unique key prefix; retry.")
            _save("tool_invocations.json", inv_rows)
            return _err("CONFLICT", "Could not allocate unique key prefix.", vendor_error="ABORTED")

    key_hash = hashlib.sha256(secret.encode("utf-8")).hexdigest()
    if len(key_hash) < 32:
        _finalize(inv_rows[-1], "failed", None, "VALIDATION_ERROR", "Internal key hash generation failed.")
        _save("tool_invocations.json", inv_rows)
        return _err("VALIDATION_ERROR", "Could not create key.", vendor_error="INTERNAL")

    # Default scopes if omitted: empty means all tools (per schema)
    eff_scopes = scopes if scopes is not None else []

    row = {
        "id": _gen_id("key"),
        "workspace_id": ws.get("id"),
        "name": name,
        "status": "active",
        "key_prefix": key_prefix,
        "key_hash": key_hash,
        "scopes": eff_scopes,
        "last_used_at": None,
        "expires_at": exp_dt.isoformat().replace("+00:00", "Z") if exp_dt is not None else None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    keys.append(row)
    _save("api_keys.json", keys)

    resp = {
        "api_key": {
            "id": row["id"],
            "workspace_id": row["workspace_id"],
            "name": row["name"],
            "status": row["status"],
            "key_prefix": row["key_prefix"],
            "scopes": row["scopes"],
            "last_used_at": row["last_used_at"],
            "expires_at": row["expires_at"],
            "created_at": row["created_at"],
            "updated_at": row["updated_at"],
        },
        "key": secret  # returned exactly once
    }
    _finalize(inv_rows[-1], "succeeded", {"api_key_id": row["id"], "key_prefix": row["key_prefix"]}, None, None)
    _save("tool_invocations.json", inv_rows)
    return resp

def update_workspace(name=None, default_timezone=None, default_time_format=None, rate_limit_per_minute=None, status=None, **_extra):
    import json, os, datetime
    from zoneinfo import ZoneInfo

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0223000" if __import__("os").path.isdir("./environment_mix/0223000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        # Best-effort parser for stored RFC3339-like timestamps
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            # Try a common fallback format
            for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S"):
                try:
                    return datetime.datetime.strptime(s, fmt).replace(tzinfo=datetime.timezone.utc)
                except Exception:
                    pass
            return None

    def _gen_id(prefix):
        return f"{prefix}_{os.urandom(12).hex()}"

    ALLOWED_FORMATS = ["h:mm A", "h:mm:ss A", "YYYY-MM-DD HH:mm:ss", "YYYY-MM-DD", "YYYY-MM", "MM/DD/YYYY", "MM/DD/YY", "YYYY/MM/DD", "YYYY/MM"]
    WS_STATUSES = ["active", "suspended", "deleted"]
    WS_TRANSITIONS = {"active": ["suspended", "deleted"], "suspended": ["active", "deleted"], "deleted": []}

    start = _now_utc()
    invocations = _load("tool_invocations.json")
    rate_counters = _load("rate_limit_counters.json")
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    tz_rows = _load("timezone_registry.json")

    # Ambient auth resolution: find any active workspace with an active, non-expired key.
    # Also auto-expire keys by policy.
    now = _now_utc()
    keys_changed = False
    for k in api_keys:
        if k.get("status") == "active" and k.get("expires_at"):
            exp = _parse_dt(k.get("expires_at"))
            if exp and now >= exp:
                k["status"] = "expired"
                k["updated_at"] = _iso(now)
                keys_changed = True
    if keys_changed:
        _save("api_keys.json", api_keys)

    def _eligible_key_for_ws(ws_id):
        for k in api_keys:
            if k.get("workspace_id") != ws_id:
                continue
            if k.get("status") != "active":
                continue
            exp = _parse_dt(k.get("expires_at")) if k.get("expires_at") else None
            if exp and now >= exp:
                continue
            return k
        return None

    authed_ws = None
    authed_key = None
    for ws in workspaces:
        if ws.get("status") != "active":
            continue
        k = _eligible_key_for_ws(ws.get("id"))
        if k:
            authed_ws = ws
            authed_key = k
            break

    created_at = _iso(start)
    inv_row = {
        "id": _gen_id("inv"),
        "workspace_id": authed_ws.get("id") if authed_ws else None,
        "api_key_id": authed_key.get("id") if authed_key else None,
        "tool_name": "current_time",  # closest enum; management tools not in tool_name enum
        "status": "failed",
        "request_params": {
            "name": name,
            "default_timezone": default_timezone,
            "default_time_format": default_time_format,
            "rate_limit_per_minute": rate_limit_per_minute,
            "status": status,
        },
        "normalized_time": None,
        "normalized_date": None,
        "source_timezone": None,
        "target_timezone": None,
        "output_format": None,
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "request_ip": None,
        "created_at": created_at,
        "updated_at": created_at,
    }

    def _finish(status_value, payload=None, err_code=None, err_msg=None):
        end = _now_utc()
        inv_row["status"] = status_value
        inv_row["updated_at"] = _iso(end)
        inv_row["duration_ms"] = max(0, int((end - start).total_seconds() * 1000))
        if payload is not None:
            inv_row["response_payload"] = payload
        if err_code is not None:
            inv_row["error_code"] = err_code
        if err_msg is not None:
            inv_row["error_message"] = err_msg
        invocations.append(inv_row)
        _save("tool_invocations.json", invocations)
        return payload if status_value == "succeeded" else _err(
            {"UNAUTHORIZED": "UNAUTHORIZED",
             "VALIDATION_ERROR": "VALIDATION_ERROR",
             "INVALID_TRANSITION": "INVALID_TRANSITION",
             "RATE_LIMIT": "RATE_LIMIT",
             "QUOTA_EXCEEDED": "QUOTA_EXCEEDED",
             "NOT_FOUND": "NOT_FOUND",
             "CONFLICT": "CONFLICT"}.get(err_code, "VALIDATION_ERROR"),
            err_msg or "Request failed.",
            error_code=err_code
        )

    # Auth check
    if not authed_ws or not authed_key:
        return _finish("failed", payload=None, err_code="UNAUTHORIZED", err_msg="Unauthorized: no active workspace/API key context available.")

    # Workspace must not be suspended/deleted for updates
    if authed_ws.get("status") in ("suspended", "deleted"):
        return _finish("failed", payload=None, err_code="UNAUTHORIZED", err_msg="Workspace is not eligible for updates (suspended or deleted).")

    # Rate limit: increment bucket for (workspace_id, api_key_id, current minute)
    window_start = now.replace(second=0, microsecond=0)
    ws_limit = authed_ws.get("rate_limit_per_minute")
    if not isinstance(ws_limit, int) or ws_limit < 1:
        ws_limit = 60

    bucket = None
    for c in rate_counters:
        if c.get("workspace_id") == authed_ws.get("id") and c.get("api_key_id") == authed_key.get("id") and c.get("window_start") == _iso(window_start):
            bucket = c
            break
    if bucket is None:
        bucket = {
            "id": _gen_id("rlc"),
            "workspace_id": authed_ws.get("id"),
            "api_key_id": authed_key.get("id"),
            "window_start": _iso(window_start),
            "count": 0,
            "status": "open",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        rate_counters.append(bucket)

    if bucket.get("status") != "open":
        # Treat sealed/expired as non-incrementable; create a new open bucket for this minute
        bucket = {
            "id": _gen_id("rlc"),
            "workspace_id": authed_ws.get("id"),
            "api_key_id": authed_key.get("id"),
            "window_start": _iso(window_start),
            "count": 0,
            "status": "open",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        rate_counters.append(bucket)

    next_count = int(bucket.get("count") or 0) + 1
    if next_count > ws_limit:
        bucket["count"] = int(bucket.get("count") or 0)  # unchanged
        bucket["updated_at"] = _iso(now)
        _save("rate_limit_counters.json", rate_counters)
        inv_row["workspace_id"] = authed_ws.get("id")
        inv_row["api_key_id"] = authed_key.get("id")
        inv_row["status"] = "rate_limited"
        inv_row["error_code"] = "RATE_LIMITED"
        inv_row["error_message"] = "Rate limit exceeded."
        return _finish("rate_limited", payload=None, err_code="RATE_LIMIT", err_msg="Rate limit exceeded.")
    bucket["count"] = next_count
    bucket["updated_at"] = _iso(now)
    _save("rate_limit_counters.json", rate_counters)

    # Update api key last_used_at
    authed_key["last_used_at"] = _iso(now)
    authed_key["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    # Validate inputs
    if name is not None:
        if not isinstance(name, str):
            return _finish("failed", None, "VALIDATION_ERROR", "name must be a string.")
        if len(name) < 1 or len(name) > 200:
            return _finish("failed", None, "VALIDATION_ERROR", "name length must be between 1 and 200.")
        # Unique(name)
        for ws in workspaces:
            if ws.get("id") != authed_ws.get("id") and ws.get("name") == name:
                return _finish("failed", None, "CONFLICT", "Workspace name already exists.")

    if default_time_format is not None:
        if not isinstance(default_time_format, str):
            return _finish("failed", None, "VALIDATION_ERROR", "default_time_format must be a string.")
        if default_time_format not in ALLOWED_FORMATS:
            return _finish("failed", None, "VALIDATION_ERROR", "Unsupported default_time_format.")

    if rate_limit_per_minute is not None:
        if not isinstance(rate_limit_per_minute, int):
            return _finish("failed", None, "VALIDATION_ERROR", "rate_limit_per_minute must be an integer.")
        # Schema constraint says <= 6000; tool param says <= 100000; enforce stricter storage constraint.
        if rate_limit_per_minute < 1 or rate_limit_per_minute > 6000:
            return _finish("failed", None, "VALIDATION_ERROR", "rate_limit_per_minute must be between 1 and 6000.")

    if status is not None:
        if not isinstance(status, str) or status not in WS_STATUSES:
            return _finish("failed", None, "VALIDATION_ERROR", "Invalid workspace status.")
        cur = authed_ws.get("status")
        if status != cur:
            allowed = WS_TRANSITIONS.get(cur, [])
            if status not in allowed:
                return _finish("failed", None, "INVALID_TRANSITION", f"Illegal workspace status transition {cur} -> {status}.")

    if default_timezone is not None:
        if not isinstance(default_timezone, str) or not default_timezone:
            return _finish("failed", None, "VALIDATION_ERROR", "default_timezone must be a non-empty string.")
        # Must be valid IANA timezone per schema. Validate with registry when possible; also validate runtime.
        tz_ok = False
        for r in tz_rows:
            if r.get("iana_name") == default_timezone and r.get("status") == "enabled":
                tz_ok = True
                break
        if not tz_ok:
            try:
                ZoneInfo(default_timezone)
                # If it exists at runtime but not enabled in registry, treat as invalid for workspace default.
                # (Schema requires valid IANA; business rules for convert_time allow insertion, but not for workspace prefs.)
                return _finish("failed", None, "VALIDATION_ERROR", "default_timezone is not enabled in timezone registry.")
            except Exception:
                return _finish("failed", None, "VALIDATION_ERROR", "Invalid IANA timezone name.")

    # Apply update
    changed = False
    if name is not None and authed_ws.get("name") != name:
        authed_ws["name"] = name
        changed = True
    if default_timezone is not None and authed_ws.get("default_timezone") != default_timezone:
        authed_ws["default_timezone"] = default_timezone
        changed = True
    if default_time_format is not None and authed_ws.get("default_time_format") != default_time_format:
        authed_ws["default_time_format"] = default_time_format
        changed = True
    if rate_limit_per_minute is not None and authed_ws.get("rate_limit_per_minute") != rate_limit_per_minute:
        authed_ws["rate_limit_per_minute"] = rate_limit_per_minute
        changed = True
    if status is not None and authed_ws.get("status") != status:
        authed_ws["status"] = status
        changed = True

    if not changed:
        # No success without effect: treat as not found-equivalent for mutation without changes
        return _finish("failed", None, "NOT_FOUND", "No changes applied.")

    authed_ws["updated_at"] = _iso(now)
    _save("workspaces.json", workspaces)

    resp = {"workspace": authed_ws}
    return _finish("succeeded", payload=resp, err_code=None, err_msg=None)

def update_api_key(id, name=None, scopes=None, expires_at=None, status=None, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0223000" if __import__("os").path.isdir("./environment_mix/0223000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    KEY_STATUSES = ["active", "revoked", "expired"]
    KEY_TRANSITIONS = {"active": ["revoked", "expired"], "revoked": [], "expired": []}
    ALLOWED_SCOPES = [
        "time:read", "time:convert", "time:relative", "time:calendar",
        "invocations:read", "keys:manage", "workspace:read", "workspace:write"
    ]

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso_z(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, "expires_at must be an RFC3339 timestamp string or null."
        t = s.strip()
        if not t:
            return None, "expires_at must be an RFC3339 timestamp string or null."
        if t.endswith("Z"):
            t = t[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(t)
        except ValueError:
            return None, "expires_at must be a valid RFC3339 timestamp."
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc), None

    def _minute_bucket(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.replace(second=0, microsecond=0)

    def _gen_id(prefix):
        return f"{prefix}_{_now_utc().strftime('%Y%m%d%H%M%S%f')}_{os.urandom(4).hex()}"

    def _log_invocation(workspace_id, api_key_id, inv_status, request_params,
                        error_code=None, error_message=None, response_payload=None, duration_ms=None):
        inv = _load("tool_invocations.json")
        if not isinstance(inv, list):
            inv = []
        now = _now_utc()
        row = {
            "id": _gen_id("tm_inv"),
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "tool_name": "update_api_key",  # not in enum; keep for audit consistency in this local server
            "status": inv_status if inv_status in ("accepted", "succeeded", "failed", "rate_limited") else "failed",
            "request_params": request_params,
            "normalized_time": None,
            "normalized_date": None,
            "source_timezone": None,
            "target_timezone": None,
            "output_format": None,
            "response_payload": response_payload,
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": duration_ms,
            "request_ip": None,
            "created_at": _iso_z(now),
            "updated_at": _iso_z(now),
        }
        inv.append(row)
        _save("tool_invocations.json", inv)

    def _increment_rate_limit(workspace_row, workspace_id, api_key_id):
        # returns (allowed:bool, counter_row_updated:bool, err_msg:str|None)
        rl = _load("rate_limit_counters.json")
        if not isinstance(rl, list):
            rl = []
        now = _now_utc()
        bucket = _minute_bucket(now)
        bucket_iso = _iso_z(bucket)
        # expire old rows (best-effort)
        changed = False
        for r in rl:
            if not isinstance(r, dict):
                continue
            wsid = r.get("workspace_id")
            if wsid != workspace_id:
                continue
            try:
                ws = r.get("window_start")
                if isinstance(ws, str):
                    wst = ws
                    if wst.endswith("Z"):
                        wst = wst[:-1] + "+00:00"
                    wdt = datetime.datetime.fromisoformat(wst)
                    if wdt.tzinfo is None:
                        wdt = wdt.replace(tzinfo=datetime.timezone.utc)
                    wdt = wdt.astimezone(datetime.timezone.utc)
                elif isinstance(ws, datetime.datetime):
                    wdt = ws.astimezone(datetime.timezone.utc)
                else:
                    continue
                if (now - wdt).total_seconds() >= 120 and r.get("status") in ("open", "sealed"):
                    r["status"] = "expired"
                    r["updated_at"] = _iso_z(now)
                    changed = True
            except Exception:
                # do not fail whole request due to a malformed historical record
                continue

        limit = workspace_row.get("rate_limit_per_minute")
        if not isinstance(limit, int) or limit < 1:
            # schema says this should not happen; treat as validation error (server-side)
            if changed:
                _save("rate_limit_counters.json", rl)
            return False, False, "Workspace rate limit misconfigured."

        # find or create bucket for workspace+api_key_id
        match = None
        for r in rl:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") == workspace_id and r.get("api_key_id") == api_key_id and r.get("window_start") == bucket_iso:
                match = r
                break
        if match is None:
            match = {
                "id": _gen_id("tm_rlc"),
                "workspace_id": workspace_id,
                "api_key_id": api_key_id,
                "window_start": bucket_iso,
                "count": 0,
                "status": "open",
                "created_at": _iso_z(now),
                "updated_at": _iso_z(now),
            }
            rl.append(match)
            changed = True

        cnt = match.get("count")
        if not isinstance(cnt, int) or cnt < 0:
            cnt = 0
        if cnt + 1 > limit:
            # do not increment; rate limited
            if changed:
                _save("rate_limit_counters.json", rl)
            return False, True, None

        match["count"] = cnt + 1
        match["updated_at"] = _iso_z(now)
        changed = True
        if changed:
            _save("rate_limit_counters.json", rl)
        return True, True, None

    start = _now_utc()

    # ---- Validate request params types/enums first (do not mutate data) ----
    if not isinstance(id, str) or not id.strip():
        # no workspace context; cannot log properly
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string.", error_code="INVALID_ARGUMENT")

    if name is not None:
        if not isinstance(name, str):
            return _err("VALIDATION_ERROR", "name must be a string.", error_code="INVALID_ARGUMENT")
        if not (1 <= len(name) <= 200):
            return _err("VALIDATION_ERROR", "name length must be between 1 and 200 characters.", error_code="INVALID_ARGUMENT")

    if scopes is not None:
        if not isinstance(scopes, list) or any(not isinstance(s, str) for s in scopes):
            return _err("VALIDATION_ERROR", "scopes must be an array of strings.", error_code="INVALID_ARGUMENT")
        bad = [s for s in scopes if s not in ALLOWED_SCOPES]
        if bad:
            return _err("VALIDATION_ERROR", "scopes contains invalid values.", error_code="INVALID_ARGUMENT", invalid_scopes=bad)

    parsed_expires = None
    if expires_at is not None:
        parsed_expires, emsg = _parse_rfc3339(expires_at)
        if emsg:
            return _err("VALIDATION_ERROR", emsg, error_code="INVALID_ARGUMENT")

    if status is not None:
        if not isinstance(status, str) or status not in KEY_STATUSES:
            return _err("VALIDATION_ERROR", "status must be one of: active, revoked, expired.", error_code="INVALID_ARGUMENT")

    # ---- Resolve authentication context (ambient) ----
    # No explicit credential parameter; choose an actually usable combination.
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    if not isinstance(workspaces, list):
        workspaces = []
    if not isinstance(api_keys, list):
        api_keys = []

    now = _now_utc()
    # auto-expire keys where needed
    keys_changed = False
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") == "active" and k.get("expires_at"):
            try:
                exs = k["expires_at"]
                t = exs[:-1] + "+00:00" if isinstance(exs, str) and exs.endswith("Z") else exs
                exdt = datetime.datetime.fromisoformat(t) if isinstance(t, str) else None
                if exdt is not None:
                    if exdt.tzinfo is None:
                        exdt = exdt.replace(tzinfo=datetime.timezone.utc)
                    exdt = exdt.astimezone(datetime.timezone.utc)
                    if now >= exdt:
                        k["status"] = "expired"
                        k["updated_at"] = _iso_z(now)
                        keys_changed = True
            except Exception:
                continue
    if keys_changed:
        _save("api_keys.json", api_keys)

    # Find the target key; accept both key id and (as observed in audit) workspace id mistakenly passed.
    target = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == id:
            target = k
            break

    target_workspace = None
    if target is not None:
        wsid = target.get("workspace_id")
        for w in workspaces:
            if isinstance(w, dict) and w.get("id") == wsid:
                target_workspace = w
                break
    else:
        # If caller passed a workspace id (audit defect), attempt to choose a key in that workspace that can be managed.
        # Prefer an active key with keys:manage scope (or empty scopes meaning all).
        for w in workspaces:
            if isinstance(w, dict) and w.get("id") == id:
                target_workspace = w
                break
        if target_workspace is not None:
            wsid = target_workspace.get("id")
            candidates = []
            for k in api_keys:
                if not isinstance(k, dict):
                    continue
                if k.get("workspace_id") != wsid:
                    continue
                if k.get("status") != "active":
                    continue
                if k.get("expires_at"):
                    try:
                        exs = k["expires_at"]
                        t = exs[:-1] + "+00:00" if isinstance(exs, str) and exs.endswith("Z") else exs
                        exdt = datetime.datetime.fromisoformat(t)
                        if exdt.tzinfo is None:
                            exdt = exdt.replace(tzinfo=datetime.timezone.utc)
                        if now >= exdt.astimezone(datetime.timezone.utc):
                            continue
                    except Exception:
                        continue
                sc = k.get("scopes")
                if not isinstance(sc, list):
                    sc = []
                if (not sc) or ("keys:manage" in sc):
                    candidates.append(k)
            if candidates:
                target = candidates[0]

    # Determine an authenticated workspace+api_key pair that satisfies prerequisites.
    # For this tool, require an active workspace and an active non-expired key if any exist; otherwise allow internal.
    auth_workspace = None
    auth_key = None

    # If we found a target, we can use its workspace as context, but we still need an active key for auth.
    if target_workspace and isinstance(target_workspace, dict) and target_workspace.get("status") == "active":
        wsid = target_workspace.get("id")
        # choose an active key for that workspace
        candidates = []
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("workspace_id") != wsid:
                continue
            if k.get("status") != "active":
                continue
            # expiry already enforced above
            sc = k.get("scopes")
            if not isinstance(sc, list):
                sc = []
            if (not sc) or ("keys:manage" in sc):
                candidates.append(k)
        if candidates:
            auth_workspace = target_workspace
            auth_key = candidates[0]
        else:
            # allow internal/system if no keys exist at all for this workspace
            any_keys = any(isinstance(k, dict) and k.get("workspace_id") == wsid for k in api_keys)
            if not any_keys:
                auth_workspace = target_workspace
                auth_key = None

    # fallback: any active workspace + usable key
    if auth_workspace is None:
        for w in workspaces:
            if not isinstance(w, dict) or w.get("status") != "active":
                continue
            wsid = w.get("id")
            candidates = []
            for k in api_keys:
                if not isinstance(k, dict):
                    continue
                if k.get("workspace_id") != wsid:
                    continue
                if k.get("status") != "active":
                    continue
                sc = k.get("scopes")
                if not isinstance(sc, list):
                    sc = []
                if (not sc) or ("keys:manage" in sc):
                    candidates.append(k)
            if candidates:
                auth_workspace = w
                auth_key = candidates[0]
                break

    request_params = {"id": id, "name": name, "scopes": scopes, "expires_at": expires_at, "status": status}

    if auth_workspace is None:
        # Log failed unauthorized without rate limiting (can't attribute reliably)
        _log_invocation(None, None, "failed", request_params, error_code="UNAUTHORIZED", error_message="No authorized workspace/key context available.")
        return _err("UNAUTHORIZED", "Unauthorized.", error_code="UNAUTHORIZED")

    workspace_id = auth_workspace.get("id")
    api_key_id = auth_key.get("id") if isinstance(auth_key, dict) else None

    # ---- Rate limit before executing ----
    allowed, _, rl_err = _increment_rate_limit(auth_workspace, workspace_id, api_key_id)
    if not allowed:
        msg = "Rate limit exceeded for this minute." if rl_err is None else rl_err
        _log_invocation(workspace_id, api_key_id, "rate_limited", request_params, error_code="RATE_LIMITED", error_message=msg)
        return _err("RATE_LIMIT", msg, error_code="RATE_LIMITED")

    # ---- Authorization: require keys:manage scope when using an API key ----
    if auth_key is not None:
        sc = auth_key.get("scopes")
        if not isinstance(sc, list):
            sc = []
        if sc and ("keys:manage" not in sc):
            _log_invocation(workspace_id, api_key_id, "failed", request_params, error_code="UNAUTHORIZED", error_message="API key lacks keys:manage scope.")
            return _err("UNAUTHORIZED", "API key lacks permission to manage keys.", error_code="UNAUTHORIZED")

    # ---- Locate the key to update; must be in authenticated workspace ----
    if target is None:
        _log_invocation(workspace_id, api_key_id, "failed", request_params, error_code="NOT_FOUND", error_message="API key not found.")
        return _err("NOT_FOUND", "API key not found.", error_code="NOT_FOUND")

    if target.get("workspace_id") != workspace_id:
        _log_invocation(workspace_id, api_key_id, "failed", request_params, error_code="UNAUTHORIZED", error_message="API key does not belong to authenticated workspace.")
        return _err("UNAUTHORIZED", "Cannot modify API keys outside the authenticated workspace.", error_code="UNAUTHORIZED")

    # ---- Apply business rules / validation against store ----
    if auth_workspace.get("status") != "active":
        _log_invocation(workspace_id, api_key_id, "failed", request_params, error_code="UNAUTHORIZED", error_message="Workspace is not active.")
        return _err("UNAUTHORIZED", "Workspace is not active.", error_code="UNAUTHORIZED")

    # unique(workspace_id, name)
    if name is not None:
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("workspace_id") == workspace_id and k.get("name") == name and k.get("id") != target.get("id"):
                _log_invocation(workspace_id, api_key_id, "failed", request_params, error_code="NAME_CONFLICT", error_message="An API key with this name already exists in the workspace.")
                return _err("CONFLICT", "unique(workspace_id, name) violated: an API key with this name already exists in the workspace.", error_code="NAME_CONFLICT")

    # expires_at constraint: null or > created_at
    if expires_at is not None:
        created = target.get("created_at")
        try:
            if isinstance(created, str):
                c = created[:-1] + "+00:00" if created.endswith("Z") else created
                cdt = datetime.datetime.fromisoformat(c)
                if cdt.tzinfo is None:
                    cdt = cdt.replace(tzinfo=datetime.timezone.utc)
                cdt = cdt.astimezone(datetime.timezone.utc)
            else:
                cdt = now
            if parsed_expires is not None and parsed_expires <= cdt:
                _log_invocation(workspace_id, api_key_id, "failed", request_params, error_code="INVALID_EXPIRES_AT", error_message="expires_at must be greater than created_at.")
                return _err("VALIDATION_ERROR", "expires_at is null or expires_at > created_at must hold.", error_code="INVALID_EXPIRES_AT")
        except Exception:
            _log_invocation(workspace_id, api_key_id, "failed", request_params, error_code="INVALID_EXPIRES_AT", error_message="expires_at validation failed.")
            return _err("VALIDATION_ERROR", "expires_at validation failed.", error_code="INVALID_EXPIRES_AT")

    # lifecycle transition validation
    if status is not None:
        cur = target.get("status")
        if cur not in KEY_STATUSES:
            # treat as server-side data issue
            _log_invocation(workspace_id, api_key_id, "failed", request_params, error_code="INVALID_TRANSITION", error_message="Current key status is invalid.")
            return _err("INVALID_TRANSITION", "Current key status is invalid; cannot transition.", error_code="INVALID_TRANSITION")
        if status != cur and status not in KEY_TRANSITIONS.get(cur, []):
            _log_invocation(workspace_id, api_key_id, "failed", request_params, error_code="INVALID_TRANSITION", error_message=f"Disallowed lifecycle transition: {cur} -> {status}.")
            return _err("INVALID_TRANSITION", f"Disallowed lifecycle transition: {cur} -> {status}.", error_code="INVALID_TRANSITION")

    # ---- Persist updates ----
    changed = False
    if name is not None and name != target.get("name"):
        target["name"] = name
        changed = True
    if scopes is not None:
        target["scopes"] = scopes
        changed = True
    if expires_at is not None or expires_at is None:
        # only update if caller provided the field (including explicit null)
        if "expires_at" not in target or (expires_at != target.get("expires_at")):
            target["expires_at"] = _iso_z(parsed_expires) if parsed_expires is not None else None
            changed = True
    if status is not None and status != target.get("status"):
        target["status"] = status
        changed = True

    # automatic expiration check after update
    if target.get("status") == "active" and target.get("expires_at"):
        try:
            exs = target["expires_at"]
            t = exs[:-1] + "+00:00" if isinstance(exs, str) and exs.endswith("Z") else exs
            exdt = datetime.datetime.fromisoformat(t)
            if exdt.tzinfo is None:
                exdt = exdt.replace(tzinfo=datetime.timezone.utc)
            exdt = exdt.astimezone(datetime.timezone.utc)
            if now >= exdt:
                # allowed transition active->expired
                target["status"] = "expired"
                changed = True
        except Exception:
            pass

    if not changed:
        # No-op update should still be treated as success only if the key exists; here it does.
        # But "NO SUCCESS WITHOUT EFFECT" rule applies to mutations matching no row; we matched a row.
        pass

    target["updated_at"] = _iso_z(now)
    if api_key_id and api_key_id == target.get("id"):
        target["last_used_at"] = _iso_z(now)

    _save("api_keys.json", api_keys)

    duration_ms = int((_now_utc() - start).total_seconds() * 1000)
    # Retention policy: include full updated row (metadata) in response_payload; callers can read it.
    resp = {
        "api_key": target,
    }
    _log_invocation(workspace_id, api_key_id, "succeeded", request_params, response_payload=resp, duration_ms=duration_ms)
    return resp

def list_timezones(page_size=None, page_token=None, status=None, iana_name_prefix=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0223000" if __import__("os").path.isdir("./environment_mix/0223000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    STATUS_ENUM = ["enabled", "disabled"]

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        t = s.strip()
        if t.endswith("Z"):
            t = t[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(t)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _minute_bucket(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.replace(second=0, microsecond=0)

    def _gen_id(prefix):
        return f"{prefix}_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S%f')}_{os.urandom(4).hex()}"

    def _decode_page_token(tok):
        if tok is None:
            return None
        if not isinstance(tok, str):
            return "INVALID", None
        t = tok.strip()
        if t == "":
            return "INVALID", None
        if t.isdigit():
            return None, {"offset": int(t)}
        try:
            padded = t + "=" * (-len(t) % 4)
            raw = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8", "strict")
            obj = json.loads(raw)
            if isinstance(obj, dict) and "offset" in obj and isinstance(obj["offset"], int) and obj["offset"] >= 0:
                return None, {"offset": obj["offset"]}
        except Exception:
            pass
        # Accept opaque tokens by treating them as "past the end" rather than rejecting
        return None, {"offset": 10**18}

    def _encode_page_token(offset):
        raw = json.dumps({"offset": int(offset)}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _auto_expire_keys(api_keys, now_dt):
        changed = False
        now_iso = _iso(now_dt)
        for k in api_keys:
            if k.get("status") == "active" and k.get("expires_at"):
                exp = _parse_rfc3339(k.get("expires_at"))
                if exp is not None and now_dt >= exp:
                    k["status"] = "expired"
                    k["updated_at"] = now_iso
                    changed = True
        return changed

    def _has_scope(key_row, needed_scope):
        scopes_val = key_row.get("scopes")
        if not isinstance(scopes_val, list) or len(scopes_val) == 0:
            return True
        return needed_scope in scopes_val

    def _resolve_auth(workspaces, api_keys):
        # Ambient auth: any active workspace with active key (timezone listing is read-only, allow any key)
        now_dt = _now_utc()
        if _auto_expire_keys(api_keys, now_dt):
            _save("api_keys.json", api_keys)
        for ws in workspaces:
            if ws.get("status") != "active":
                continue
            ws_id = ws.get("id")
            if not isinstance(ws_id, str) or not ws_id:
                continue
            for k in api_keys:
                if k.get("workspace_id") != ws_id:
                    continue
                if k.get("status") != "active":
                    continue
                exp = _parse_rfc3339(k.get("expires_at")) if k.get("expires_at") else None
                if exp is not None and now_dt >= exp:
                    continue
                # no specific scope required for list_timezones
                return ws, k
        return None, None

    started = _now_utc()
    invocations = _load("tool_invocations.json")
    rate_counters = _load("rate_limit_counters.json")
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    timezones = _load("timezone_registry.json")

    # Validate inputs
    if page_size is None:
        page_size = 200
    if not isinstance(page_size, int):
        return _err("VALIDATION_ERROR", "page_size must be an integer.", error_code="VALIDATION_ERROR")
    if page_size < 1 or page_size > 500:
        return _err("VALIDATION_ERROR", "page_size must be between 1 and 500.", error_code="VALIDATION_ERROR")
    if status is not None:
        if not isinstance(status, str) or status not in STATUS_ENUM:
            return _err("VALIDATION_ERROR", "Invalid status.", error_code="VALIDATION_ERROR")
    if iana_name_prefix is not None and not isinstance(iana_name_prefix, str):
        return _err("VALIDATION_ERROR", "iana_name_prefix must be a string.", error_code="VALIDATION_ERROR")

    tok_err, tok = _decode_page_token(page_token)
    if tok_err == "INVALID":
        return _err("VALIDATION_ERROR", "Invalid page_token.", error_code="VALIDATION_ERROR")

    ws, key = _resolve_auth(workspaces, api_keys)
    now_dt = _now_utc()
    if ws is None or key is None:
        inv_id = _gen_id("tm_inv")
        inv = {
            "id": inv_id,
            "workspace_id": "unknown",
            "api_key_id": None,
            "tool_name": "current_time",
            "status": "failed",
            "request_params": {"page_size": page_size, "page_token": page_token, "status": status, "iana_name_prefix": iana_name_prefix},
            "normalized_time": None,
            "normalized_date": None,
            "source_timezone": None,
            "target_timezone": None,
            "output_format": "YYYY-MM-DD HH:mm:ss",
            "response_payload": None,
            "error_code": "UNAUTHORIZED",
            "error_message": "Unauthorized.",
            "duration_ms": int((now_dt - started).total_seconds() * 1000),
            "request_ip": None,
            "created_at": _iso(started),
            "updated_at": _iso(now_dt),
        }
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("UNAUTHORIZED", "Unauthorized.", error_code="UNAUTHORIZED")

    ws_id = ws["id"]
    key_id = key["id"]

    # Rate limit increment BEFORE serving
    minute = _minute_bucket(now_dt)
    minute_iso = _iso(minute)
    rl_limit = ws.get("rate_limit_per_minute")
    if not isinstance(rl_limit, int) or rl_limit < 1:
        rl_limit = 60

    bucket = None
    for r in rate_counters:
        if r.get("workspace_id") == ws_id and r.get("api_key_id") == key_id and r.get("window_start") == minute_iso:
            bucket = r
            break
    if bucket is None:
        bucket = {
            "id": _gen_id("tm_rlc"),
            "workspace_id": ws_id,
            "api_key_id": key_id,
            "window_start": minute_iso,
            "count": 0,
            "status": "open",
            "created_at": _iso(now_dt),
            "updated_at": _iso(now_dt),
        }
        rate_counters.append(bucket)

    if not isinstance(bucket.get("count"), int) or bucket["count"] < 0:
        bucket["count"] = 0

    if bucket["count"] + 1 > rl_limit:
        bucket["status"] = "sealed"
        bucket["updated_at"] = _iso(now_dt)
        _save("rate_limit_counters.json", rate_counters)

        inv_id = _gen_id("tm_inv")
        inv = {
            "id": inv_id,
            "workspace_id": ws_id,
            "api_key_id": key_id,
            "tool_name": "current_time",
            "status": "rate_limited",
            "request_params": {"page_size": page_size, "page_token": page_token, "status": status, "iana_name_prefix": iana_name_prefix},
            "normalized_time": None,
            "normalized_date": None,
            "source_timezone": None,
            "target_timezone": None,
            "output_format": "YYYY-MM-DD HH:mm:ss",
            "response_payload": None,
            "error_code": "RATE_LIMITED",
            "error_message": "Rate limit exceeded for this minute.",
            "duration_ms": int((_now_utc() - started).total_seconds() * 1000),
            "request_ip": None,
            "created_at": _iso(started),
            "updated_at": _iso(_now_utc()),
        }
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("RATE_LIMIT", "Rate limit exceeded for this minute.", error_code="RATE_LIMITED")

    bucket["count"] += 1
    bucket["updated_at"] = _iso(now_dt)
    _save("rate_limit_counters.json", rate_counters)

    # Update key last_used_at
    key["last_used_at"] = _iso(now_dt)
    key["updated_at"] = _iso(now_dt)
    _save("api_keys.json", api_keys)

    # Apply filters
    rows = timezones
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if iana_name_prefix is not None:
        rows = [r for r in rows if isinstance(r.get("iana_name"), str) and r.get("iana_name").startswith(iana_name_prefix)]

    # Sort by iana_name ascending (stable)
    def _name_key(r):
        n = r.get("iana_name")
        return n if isinstance(n, str) else ""
    rows = sorted(rows, key=_name_key)

    total = len(rows)
    offset = 0
    if tok is not None and "offset" in tok:
        offset = tok["offset"]
    if not isinstance(offset, int) or offset < 0:
        offset = 0
    if offset > total:
        offset = total

    page = rows[offset:offset + page_size]
    has_more = (offset + page_size) < total
    next_token = _encode_page_token(offset + page_size) if has_more else None

    ended = _now_utc()
    inv_id = _gen_id("tm_inv")
    inv = {
        "id": inv_id,
        "workspace_id": ws_id,
        "api_key_id": key_id,
        "tool_name": "current_time",
        "status": "succeeded",
        "request_params": {"page_size": page_size, "page_token": page_token, "status": status, "iana_name_prefix": iana_name_prefix},
        "normalized_time": None,
        "normalized_date": None,
        "source_timezone": None,
        "target_timezone": None,
        "output_format": "YYYY-MM-DD HH:mm:ss",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": int((ended - started).total_seconds() * 1000),
        "request_ip": None,
        "created_at": _iso(started),
        "updated_at": _iso(ended),
    }
    invocations.append(inv)
    _save("tool_invocations.json", invocations)

    return {
        "timezones": page,
        "page_size": page_size,
        "next_page_token": next_token,
        "has_more": has_more,
        "total": total,
    }
